-- Update only isolated staging copy; retain prior CMS snapshots for recovery.
WITH changes AS (SELECT * FROM jsonb_to_recordset($copy$[{"slot": "contact.018", "html": "How can we help?"}, {"slot": "contact.019", "html": "Questions, partnership opportunities, press inquiries, or something else? Send the LOLA team a message. For event availability and a personalized quote, use our booking form."}, {"slot": "contact.021", "html": "Ask about our services, an existing booking, or anything else you would like to know."}, {"slot": "contact.026", "html": "Partnership Opportunities"}, {"slot": "contact.027", "html": "Interested in working with LOLA as a venue, planner, brand, or creative partner? We would love to hear from you."}, {"slot": "contact.028", "html": "Talk about a partnership \u2192"}, {"slot": "contact.030", "html": "Start a conversation."}, {"slot": "contact.031", "html": "Tell us how we can help. No event date, venue, or package selection is needed to send a message."}, {"slot": "contact.036", "html": "Send a Message"}, {"slot": "contact.037", "html": "What would you like to talk about?"}, {"slot": "contact.040", "html": "A conversation starts here."}, {"slot": "contact.041", "html": "We will review your message and connect you with the right person."}, {"slot": "contact.043", "html": "Choose a topic and tell us how we can help."}, {"slot": "contact.044", "html": "We read your message"}, {"slot": "contact.045", "html": "Our team reviews your question or partnership idea."}, {"slot": "contact.046", "html": "We get back to you"}, {"slot": "contact.047", "html": "We reply using the email address you provide."}, {"slot": "contact.048", "html": "Continue the conversation"}, {"slot": "contact.049", "html": "Share any additional details with our team. Sending a message does not create or reserve a booking."}, {"slot": "contact.050", "html": "Partnerships & Collaborations"}, {"slot": "contact.051", "html": "Let\u2019s work together."}, {"slot": "contact.052", "html": "Venues, event planners, creative teams, and brands: tell us about your organization and the opportunity you have in mind."}, {"slot": "contact.053", "html": "Send a Partnership Inquiry \u2192"}, {"slot": "contact.067", "html": "Have a question?"}, {"slot": "contact.068", "html": "Send a message about our services, a partnership, or anything else. We are here to help."}, {"slot": "contact.069", "html": "Contact the Team \u2192", "href": "#contact-form"}, {"slot": "availability.017", "html": "Booking Request"}, {"slot": "availability.018", "html": "Check availability for your event."}, {"slot": "availability.019", "html": "Tell us your event date, location, guest count, and preferred experience. We will check availability and prepare a personalized quote. This form does not confirm a reservation."}, {"slot": "availability.022", "html": "Use this form for an event booking request. For general questions, partnerships, or help with an existing booking, please use Contact instead."}]$copy$::jsonb) AS x(slot text,html text,href text)), previous AS (
 INSERT INTO website_content_versions(entity_type,entity_id,snapshot,action)
 SELECT 'staging:pageItems',r.id,to_jsonb(r),'updated' FROM website_channel_records r JOIN changes c ON r.payload->>'slot_key'=c.slot WHERE r.channel='STAGING' AND r.cms_type='pageItems' RETURNING entity_id
)
UPDATE website_channel_records r SET payload=r.payload||jsonb_build_object('html',c.html)||CASE WHEN c.href IS NOT NULL THEN jsonb_build_object('href',c.href) ELSE '{}'::jsonb END,updated_at=now()
FROM changes c WHERE r.channel='STAGING' AND r.cms_type='pageItems' AND r.payload->>'slot_key'=c.slot;
